			ushort tokusei = (ushort)bpp.GetValue(BTL_POKEPARAM.ValueID.BPP_TOKUSEI);
			HandlerGetFunc func = getHandlerGetFunc((TokuseiNo)tokusei);
			if (func == null)
				return;

			prio = EventPriority.TOKUSEI;
			EventFactor.EventHandlerTable[] handlerTable = func(ref prio);
			if (handlerTable == null)
				return;

			pEventSystem.AddFactor(EventFactorType.TOKUSEI, tokusei, prio, (ushort)bpp.GetValue_Base(BTL_POKEPARAM.ValueID.BPP_AGILITY), bpp.GetID(), handlerTable, (byte)handlerTable.Length);
		}
		public static void Remove(global::Dpr.Battle.Logic.EventSystem pEventSystem, global::Dpr.Battle.Logic.BTL_POKEPARAM bpp) {
			// 0193ea40: the container is read BEFORE GetID; the search restarts after every removal and stops at the first
			// factor whose WIDX_REMOVE_GUARD work value is set
			EventFactorContainer container = pEventSystem.GetFactorContainer();
			byte dependID = bpp.GetID();
			EventFactor factor = container.SeekFactor(EventFactorType.TOKUSEI, dependID);
			while (factor != null && factor.GetWorkValue(WIDX_REMOVE_GUARD) == FALSE)
			{
				pEventSystem.RemoveFactor(factor);
				factor = container.SeekFactor(EventFactorType.TOKUSEI, dependID);
			}
		}
		public static void Swap(global::Dpr.Battle.Logic.EventSystem pEventSystem, global::Dpr.Battle.Logic.BTL_POKEPARAM pp1, global::Dpr.Battle.Logic.BTL_POKEPARAM pp2) {
			EventFactorContainer container = pEventSystem.GetFactorContainer();
			byte pokeID1 = pp1.GetID();
			byte pokeID2 = pp2.GetID();
			EventFactor factor1 = container.SeekFactor(EventFactorType.TOKUSEI, pokeID1);
			EventFactor factor2 = container.SeekFactor(EventFactorType.TOKUSEI, pokeID2);
			if (factor1 != null)
				pEventSystem.RemoveFactor(factor1);
			if (factor2 != null)
				pEventSystem.RemoveFactor(factor2);

			Add(pEventSystem, pp1);
			Add(pEventSystem, pp2);
		}
