		public static void handler_Ikaku_MemberIn(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;

			var exPos = new ExPokePos(ExPokePos.ExPosType.AREA_ENEMY, Common.GetExistFrontPokePos(args, pokeID));
			byte[] targetPokeID = new byte[5];
			byte targetCount = Common.ExpandExistPokeID(args, exPos, targetPokeID);
			if (targetCount == 0)
				return;

			Common.TokuseiWindow_In(args, pokeID);

			var desc = new Section_FromEvent_RankEffect.Description();
			desc.pokeID = pokeID;
			desc.rankType = WazaRankEffect.ATTACK;
			desc.rankVolume = -1;
			desc.cause = RankEffectCause.IKAKU;
			desc.isSpFailMessageDisplay = true;
			desc.targetPokeCount = targetCount;
			for (int i = 0; i < targetCount; i++)
				desc.targetPokeID[i] = targetPokeID[i];

			Common.RankEffect(args, desc);
			Common.TokuseiWindow_Out(args, pokeID);
		}
