			Common.SetWorkValue(args, WIDX0, 1);
			Common.SetWorkValue(args, WIDX1, 0);
			Common.SetWorkValue(args, WIDX2, 0);
			Common.SetWorkValue(args, WIDX3, 1);

			var desc = new Section_FromEvent_Message.Description();
			desc.pokeID = pokeID;
			desc.isDisplayTokuseiWindow = true;
			desc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.SlowStartON);
