		public static void handler_SlowStart_TurnCheck(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;

			if (Common.GetWorkValue(args, WIDX2) != 0)
				return;

			int turn = Common.GetWorkValue(args, WIDX1);
			if (turn < 5)
			{
				PokeAction action = args.pPokeActionContainer.SearchByPokeID(pokeID, true, false);
				if (action == null || action.actionCategory == PokeActionCategory.PokeChange)
					return;

				Common.SetWorkValue(args, WIDX1, turn + 1);
				if (turn < 4)
					return;
			}

			var desc = new Section_FromEvent_Message.Description();
			desc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.SlowStartOFF);
			desc.message.AddArg(pokeID);
			Common.Message(args, desc);
			Common.SetWorkValue(args, WIDX3, 0);
			Common.SetWorkValue(args, WIDX2, 1);
		}
