		public static void common_hpborder_powerup(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, in byte pokeID, in byte wazaType) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;

			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			uint border = calc.QuotMaxHP_Zero(bpp, 3, false);
			if ((uint)bpp.GetValue(BTL_POKEPARAM.ValueID.BPP_HP) > border)
				return;

			if (Common.GetEventVar(args, EventVar.Label.WAZA_TYPE) == wazaType)
				Common.MulEventVar(args, EventVar.Label.RATIO, 0x1800);
		}
