		public static void handler_Konjou(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;

			if (Common.GetPokeParam(args, pokeID).GetPokeSick() == Pml.PokePara.Sick.NONE)
				return;

			// 01941e00: the damage type is compared as a ushort (`and #0xffff`)
			if ((ushort)Common.GetEventVar(args, EventVar.Label.DAMAGE_TYPE) != (ushort)WazaDamageType.PHYSIC)
				return;

