		public static void handler_PlusMinus(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;

			if (!checkExistTokuseiFriend(args, pokeID, TokuseiNo.PURASU) && !checkExistTokuseiFriend(args, pokeID, TokuseiNo.MAINASU))
				return;

			if (Common.GetEventVar(args, EventVar.Label.DAMAGE_TYPE) == (int)WazaDamageType.SPECIAL)
				Common.MulEventVar(args, EventVar.Label.RATIO, 0x1800);
		}
		public static bool checkExistTokuseiFriend(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID, global::Pml.TokuseiNo tokuseiID) {
			BtlPokePos pos = Common.PokeIDtoPokePos(args, pokeID);
			if (pos == BtlPokePos.POS_NULL)
				return false;

			var exPos = new ExPokePos(ExPokePos.ExPosType.FULL_FRIENDS, pos);
			byte[] friendPokeID = new byte[7];
			byte count = Common.ExpandExistPokeID(args, exPos, friendPokeID);
			for (int i = 0; i < count; i++)
			{
				if (friendPokeID[i] == pokeID)
					continue;

				// 0194213c: the tokusei is compared as a ushort
				if (Common.GetPokeParam(args, friendPokeID[i]).GetValue(BTL_POKEPARAM.ValueID.BPP_TOKUSEI_EFFECTIVE) == (ushort)tokuseiID)
					return true;
			}

			return false;
		}
