		public static void common_FlowerGift_FormChange(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID, byte nextForm, byte fTokWin) {
			if (Common.GetPokeParam(args, pokeID).GetFormNo() == nextForm)
				return;

			var desc = new Section_FromEvent_FormChange.Description();
			desc.pokeID = pokeID;
			desc.formNo = nextForm;
			desc.isDisplayTokuseiWindow = fTokWin != 0;
			desc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.ChangeForm);
			desc.successMessage.AddArg(pokeID);
			Common.FormChange(args, desc);
		}
