		public static void handler_Tousousin(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;

			byte defPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_DEF);
			BTL_POKEPARAM attacker = Common.GetPokeParam(args, pokeID);
			BTL_POKEPARAM defender = Common.GetPokeParam(args, defPokeID);
			Pml.Sex atkSex = (Pml.Sex)attacker.GetValue(BTL_POKEPARAM.ValueID.BPP_SEX);
			Pml.Sex defSex = (Pml.Sex)defender.GetValue(BTL_POKEPARAM.ValueID.BPP_SEX);
			if (atkSex == Pml.Sex.UNKNOWN || defSex == Pml.Sex.UNKNOWN)
				return;

			Common.MulEventVar(args, EventVar.Label.WAZA_POWER_RATIO, atkSex == defSex ? 0x1400 : 0xC00);
		}
