		public static void common_RankDownGuard_Check(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, in byte pokeID, in global::Pml.WazaData.WazaRankEffect rankType) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;

			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) == pokeID)
				return;

			if (Common.GetEventVar(args, EventVar.Label.STATUS_TYPE) == (int)WazaRankEffect.CRITICAL_RATIO)
				return;

			// rankType MAX = every stat
			if (rankType != WazaRankEffect.MAX && Common.GetEventVar(args, EventVar.Label.STATUS_TYPE) != (int)rankType)
				return;

			if (Common.GetEventVar(args, EventVar.Label.VOLUME) < 0)
			{
				bool isRewrite = Common.RewriteEventVar(args, EventVar.Label.FAIL_FLAG, TRUE);
				Common.SetWorkValue(args, WIDX0, isRewrite ? 1 : 0);
			}
		}
		public static void common_RankDownGuard_Fixed(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, in byte pokeID, in byte tokwin_pokeID, in ushort strID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;

			if (Common.GetWorkValue(args, WIDX0) == 0)
				return;

			Common.SetWorkValue(args, WIDX0, 0);

			// one message per move execution (the serial of the last message is kept in work[1])
			int wazaSerial = Common.GetEventVar(args, EventVar.Label.WAZA_SERIAL);
			if (wazaSerial != 0 && Common.GetWorkValue(args, WIDX1) == wazaSerial)
				return;

			var desc = new Section_FromEvent_Message.Description();
			desc.isDisplayTokuseiWindow = true;
			desc.pokeID = tokwin_pokeID;
			desc.message.Setup(BtlStrType.BTL_STRTYPE_SET, strID);
			desc.message.AddArg(pokeID);
			desc.message.SetFailMsgFlag();
			Common.Message(args, desc);
			Common.SetWorkValue(args, WIDX1, wazaSerial);
		}
