		public static void handler_LeafGuard(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_DEF) != pokeID)
				return;

			if (!common_IsShineLocalWeather(args, pokeID))
				return;

			// 01944808: IsBasicSickID is called before the AKUBI compare (left operand of ||)
			WazaSick sick = (WazaSick)Common.GetEventVar(args, EventVar.Label.SICKID);
			if (calc.IsBasicSickID(sick) || sick == WazaSick.WAZASICK_AKUBI)
			{
				bool isRewrite = Common.RewriteEventVar(args, EventVar.Label.FAIL_FLAG, TRUE);
				Common.SetWorkValue(args, WIDX0, isRewrite ? 1 : 0);
			}
		}
