		public static void handler_Donkan_NoEffCheck(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_DEF) != pokeID)
				return;

			WazaNo waza = (WazaNo)Common.GetEventVar(args, EventVar.Label.WAZAID);
			if (waza != WazaNo.YUUWAKU && waza != WazaNo.TYOUHATU)
				return;

			if (!Common.RewriteEventVar(args, EventVar.Label.NOEFFECT_FLAG, TRUE))
				return;

			Common.TokuseiWindow_In(args, pokeID);
			var desc = new Section_FromEvent_Message.Description();
			desc.pokeID = pokeID;
			desc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.NoEffect);
			desc.message.AddArg(pokeID);
			Common.Message(args, desc);
			Common.TokuseiWindow_Out(args, pokeID);
			Common.RewriteEventVar(args, EventVar.Label.MESSAGE_DISPLAYED, TRUE);
		}
		public static void common_AddSickFailed(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID, ushort strID) {
