		public static void common_FriendCureSick(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID, global::Pml.WazaData.WazaSick cureSick) {
			var exPos = new ExPokePos(ExPokePos.ExPosType.AREA_MYTEAM, Common.GetExistFrontPokePos(args, pokeID));
			byte[] friendPokeID = new byte[6];
			byte count = Common.ExpandExistPokeID(args, exPos, friendPokeID);
			if (count == 0)
				return;

			var desc = new Section_CureSick.Description();
			desc.pokeID = pokeID;
			desc.targetPokeCount = 0;
			for (int i = 0; i < count; i++)
			{
				byte friendID = friendPokeID[i];
				if (Common.GetPokeParam(args, friendID).CheckSick(cureSick))
				{
					desc.targetPokeID[desc.targetPokeCount] = friendID;
					desc.targetPokeCount++;
				}
			}

			desc.sick = (WazaSickEx)cureSick;
			desc.isDisplayTokuseiWindow = true;
			if (desc.targetPokeCount != 0)
				Common.CureSick(args, desc);
		}
