		public static void common_weather_change(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID, global::Dpr.Battle.Logic.BtlWeather weather, ushort boostItem, bool isPermanent) {
			byte turnUpCount = 0;
			byte turn = 5;
			if (boostItem != 0 && Common.GetPokeParam(args, pokeID).GetItem() == boostItem && Common.CheckItemUsable(args, pokeID))
			{
				turnUpCount = (byte)calc.ITEM_GetParam(boostItem, Pml.Item.ItemData.PrmID.ATTACK);
				turn = (byte)(turnUpCount + 5);
			}

			if (isPermanent)
				turn = 0xFF;

			var desc = new Section_FromEvent_ChangeWeather.Description();
			desc.userPokeID = pokeID;
			desc.isDisplayTokuseiWindow = true;
			desc.weather = weather;
			desc.turn = turn;
			desc.turnUpCount = turnUpCount;
			Common.ChangeWeather(args, desc);
		}
		public static void common_weather_stop(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID, global::Dpr.Battle.Logic.BtlWeather weather) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;

			if (Common.GetWeather_True(args) != weather)
				return;

			if (Common.GetDefaultWeather(args) == weather)
				return;

			var desc = new Section_FromEvent_ChangeWeather.Description();
			desc.userPokeID = pokeID;
			desc.weather = BtlWeather.BTL_WEATHER_NONE;
			desc.turn = 0;
			desc.isDisplayTokuseiWindow = true;
			Common.ChangeWeather(args, desc);
		}
		public static bool common_check_tokusei(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte selfPokeId, ushort tokusei) {
			// 01947674: the array is allocated before the position lookup
			byte[] pokeIDs = new byte[6];
			var exPos = new ExPokePos(ExPokePos.ExPosType.FULL_ALL, Common.GetExistFrontPokePos(args, selfPokeId));
			byte count = Common.ExpandExistPokeID(args, exPos, pokeIDs);
			for (int i = 0; i < count; i++)
			{
				if (pokeIDs[i] == selfPokeId)
					continue;

				if ((ushort)Common.GetPokeParam(args, pokeIDs[i]).GetValue(BTL_POKEPARAM.ValueID.BPP_TOKUSEI_EFFECTIVE) == tokusei)
					return true;
			}

			return false;
		}
