		public static void common_weather_recover(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID, global::Dpr.Battle.Logic.BtlWeather weather) {
			// 01948220: the event weather is replaced by SHINE / RAIN when the local weather is a shine / rain kind
			BtlWeather localWeather = Common.GetLocalWeather(args, pokeID);
			BtlWeather eventWeather = (BtlWeather)Common.GetEventVar(args, EventVar.Label.WEATHER);
			if (calc.IsShineWeather(localWeather))
				eventWeather = BtlWeather.BTL_WEATHER_SHINE;
			if (calc.IsRainWeather(localWeather))
				eventWeather = BtlWeather.BTL_WEATHER_RAIN;

			if (eventWeather != weather)
				return;

			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;

			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			var desc = new Section_RecoverHP.Description();
			desc.userPokeID = pokeID;
			desc.targetPokeID = pokeID;
			desc.recoverHP = (ushort)calc.QuotMaxHP(bpp, 16, true);
			desc.isDisplayTokuseiWindow = true;
			Common.RecoverHP(args, desc);
			Common.RewriteEventVar(args, EventVar.Label.FAIL_FLAG, TRUE);
		}
