		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_Housi(ref global::Dpr.Battle.Logic.EventPriority prio) {
			return HandlerTable_Housi;
		}
		public static void handler_Housi(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_DEF) != pokeID)
				return;

			if (Common.GetEventVar(args, EventVar.Label.MIGAWARI_FLAG) != 0)
				return;

			byte atkPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_ATK);
			BTL_POKEPARAM attacker = Common.GetPokeParam(args, atkPokeID);
			if (attacker.IsMatchType((byte)PokeType.KUSA))
				return;

			if (attacker.GetValue(BTL_POKEPARAM.ValueID.BPP_TOKUSEI_EFFECTIVE) == (int)TokuseiNo.BOUZIN)
				return;

			if (Common.GetUsableItem(args, atkPokeID) == (ushort)ItemNo.BOUZINGOOGURU)
				return;

			// 0194a4a0: 0..10 NEMURI, 11..20 MAHI, 21..29 DOKU (unsigned compares)
			uint rand = calc.GetRand(30);
			Pml.PokePara.Sick sick;
			if (rand > 20)
				sick = Pml.PokePara.Sick.DOKU;
			else if (rand <= 10)
				sick = Pml.PokePara.Sick.NEMURI;
			else
				sick = Pml.PokePara.Sick.MAHI;

			BTL_SICKCONT sickCont = calc.MakeDefaultPokeSickCont(sick, pokeID, false);
			common_touchAddSick(args, pokeID, (WazaSick)sick, sickCont, 30);
		}
		public static void common_touchAddSick(global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID, global::Pml.WazaData.WazaSick sick, in global::Dpr.Battle.Logic.BTL_SICKCONT sickCont, byte per) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_DEF) != pokeID)
				return;

			if (Common.GetEventVar(args, EventVar.Label.MIGAWARI_FLAG) != 0)
				return;

			if (Common.GetEventVar(args, EventVar.Label.WAZA_TOUCH_FLAG) == 0)
				return;

			// isOccurPer inlined (its init flag)
			if (!isOccurPer(args, per))
				return;

			var desc = new Section_AddSick.Description();
			desc.pokeID = pokeID;
			desc.isDisplayTokuseiWindow = true;
			desc.sickID = sick;
			desc.sickCont = sickCont;
			desc.sickCause = SickCause.TOKUSEI_TOUCH_COUNTER;
			desc.isFailResultDisplay = false;
			desc.targetPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_ATK);
			Common.AddSick(args, desc);
		}
		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_Samehada(ref global::Dpr.Battle.Logic.EventPriority prio) {
