		public static void handler_Samehada(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_DEF) != pokeID)
				return;

			if (Common.GetEventVar(args, EventVar.Label.MIGAWARI_FLAG) != 0)
				return;

			if (Common.GetEventVar(args, EventVar.Label.WAZA_TOUCH_FLAG) == 0)
				return;

			byte atkPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_ATK);
			BTL_POKEPARAM attacker = Common.GetPokeParam(args, atkPokeID);
			if (attacker.IsDead())
				return;

			ushort tokusei = Common.GetSubID(args);
			DamageCause cause = tokusei == (ushort)TokuseiNo.SAMEHADA ? DamageCause.SAMEHADA
							  : tokusei == (ushort)TokuseiNo.TETUNOTOGE ? DamageCause.TETUNOTOGE
							  : DamageCause.OTHER;

			var desc = new Section_FromEvent_Damage.Description();
			desc.pokeID = pokeID;
			desc.targetPokeID = atkPokeID;
			desc.damage = (ushort)calc.QuotMaxHP(attacker, 8, true);
			desc.damageCause = cause;
			desc.damageCausePokeID = pokeID;
			desc.disableDeadProcess = true;
			desc.isDisplayTokuseiWindow = true;
			desc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.Samehada);
			desc.successMessage.AddArg(atkPokeID);
			Common.Damage(args, desc);
		}
