		public static void handler_HorobiNoSango(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_DEF) != pokeID)
				return;

			if (Common.GetEventVar(args, EventVar.Label.MIGAWARI_FLAG) != 0)
				return;

			if (Common.GetEventVar(args, EventVar.Label.WAZA_TOUCH_FLAG) == 0)
				return;

			BTL_POKEPARAM attacker = Common.GetPokeParam(args, (byte)Common.GetEventVar(args, EventVar.Label.POKEID_ATK));
			BTL_POKEPARAM self = Common.GetPokeParam(args, pokeID);
			if (attacker.IsRaidBoss() || self.IsRaidBoss())
				return;

			// the holder gets Perish Song only when the attacker got it
			if (!common_Horobinouta(args, pokeID, attacker))
				return;

			common_Horobinouta(args, pokeID, self);

			var desc = new Section_FromEvent_Message.Description();
			desc.pokeID = pokeID;
			desc.isDisplayTokuseiWindow = true;
			desc.message.Setup(BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.HorobiNoSango);
			Common.Message(args, desc);
		}
