		public static void handler_Hensyoku(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (!Common.CheckTargetPokeID(args, pokeID))
				return;

			if (Common.CheckShowDown(args))
				return;

			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			if (bpp.IsDead())
				return;

			byte wazaType = (byte)Common.GetEventVar(args, EventVar.Label.WAZA_TYPE);
