		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_Syncro(ref global::Dpr.Battle.Logic.EventPriority prio) {
			return HandlerTable_Syncro;
		}
		public static void handler_Syncro(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			int defPokeID = Common.GetEventVar(args, EventVar.Label.POKEID_DEF);
			if (defPokeID != pokeID)
				return;

			// 0194b170: `sick <= 5 (unsigned) && (1 << sick) & 0x32` = MAHI / YAKEDO / DOKU
			WazaSick sick = (WazaSick)Common.GetEventVar(args, EventVar.Label.SICKID);
			if (sick != WazaSick.WAZASICK_MAHI && sick != WazaSick.WAZASICK_YAKEDO && sick != WazaSick.WAZASICK_DOKU)
				return;

			int atkPokeID = Common.GetEventVar(args, EventVar.Label.POKEID_ATK);
			if ((byte)atkPokeID == PokeID.INVALID || (byte)atkPokeID == defPokeID)
				return;

			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			BTL_SICKCONTOBJ sickContObj = (BTL_SICKCONTOBJ)Common.GetEventVarAddress(args, EventVar.Label.SICK_CONT_ADRS);

			var desc = new Section_AddSick.Description();
			desc.pokeID = pokeID;
			desc.targetPokeID = (byte)atkPokeID;
			desc.sickID = sick;
			if (sick == WazaSick.WAZASICK_DOKU && SICKCONT.IsMoudokuCont(sickContObj.value))
			{
				// bad poison is passed back as bad poison, with the holder as its cause
				desc.sickCont = sickContObj.value;
				SICKCONT.SetCausePokeID(ref desc.sickCont, pokeID);
			}
			else
			{
				calc.MakeDefaultWazaSickCont(sick, bpp, out desc.sickCont);
			}

			desc.isDisplayTokuseiWindow = true;
			desc.isFailResultDisplay = true;
			Common.AddSick(args, desc);
		}
