			return HandlerTable_Trace;
		}
		public static void handler_Trace(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			byte eventPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID);
			int tokuseiID;
			byte targetPokeID;
			if (eventPokeID == pokeID)
			{
				// the Trace user came in: copy a random traceable ability from the opposing front
				byte[] enemyPokeID = new byte[5];
				byte[] candidates = new byte[5];
				var exPos = new ExPokePos(ExPokePos.ExPosType.AREA_ENEMY, Common.GetExistFrontPokePos(args, pokeID));
				byte count = Common.ExpandExistPokeID(args, exPos, enemyPokeID);
				byte candidateCount = 0;
				for (int i = 0; i < count; i++)
				{
					int enemyTokusei = Common.GetPokeParam(args, enemyPokeID[i]).GetValue(BTL_POKEPARAM.ValueID.BPP_TOKUSEI);
					if (!tables.CheckTraceFailTokusei((TokuseiNo)enemyTokusei))
						candidates[candidateCount++] = enemyPokeID[i];
				}

				if (candidateCount == 0)
				{
					// nothing to trace now: wait for the next opponent to come in
					Common.SetWorkValue(args, WIDX0, 1);
					return;
				}

				byte idx = candidateCount == 1 ? (byte)0 : (byte)calc.GetRand(candidateCount);
				BTL_POKEPARAM target = Common.GetPokeParam(args, candidates[idx]);
				tokuseiID = target.GetValue(BTL_POKEPARAM.ValueID.BPP_TOKUSEI);
				targetPokeID = target.GetID();
			}
			else
			{
				// an opponent came in while Trace is still waiting
				if (Common.IsFriendPokeID(args, eventPokeID, pokeID))
					return;

				if (Common.GetWorkValue(args, WIDX0) != 1)
					return;

				if (Common.PokeIDtoPokePos(args, eventPokeID) == BtlPokePos.POS_NULL)
					return;

				tokuseiID = Common.GetPokeParam(args, eventPokeID).GetValue(BTL_POKEPARAM.ValueID.BPP_TOKUSEI);
				if (tables.CheckTraceFailTokusei((TokuseiNo)tokuseiID))
					return;

				targetPokeID = eventPokeID;
			}

			if (pokeID == PokeID.INVALID || tokuseiID == 0)
				return;

			var desc = new Section_FromEvent_ChangeTokusei.Description();
			desc.userPokeID = pokeID;
			desc.targetPokeID = pokeID;
			desc.tokuseiID = (TokuseiNo)tokuseiID;
			desc.isSkipMemberInEvent = true;
			desc.isDisplayTokuseiWindow = true;
			desc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.Trace);
			desc.successMessage.AddArg(targetPokeID);
			desc.successMessage.AddArg(tokuseiID);
			Common.ChangeTokusei(args, desc);
		}
