		public static void handler_Download(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;

			byte[] opponentPokeID = new byte[5];
			byte count = Common.GetAllOpponentFrontPokeID(args, pokeID, opponentPokeID);
			if (count == 0)
				return;

			ushort defence = 0;
			ushort spDefence = 0;
			for (int i = 0; i < count; i++)
			{
				BTL_POKEPARAM bpp = Common.GetPokeParam(args, opponentPokeID[i]);
				defence += (ushort)bpp.GetValue(BTL_POKEPARAM.ValueID.BPP_DEFENCE);
				spDefence += (ushort)bpp.GetValue(BTL_POKEPARAM.ValueID.BPP_SP_DEFENCE);
			}

			var desc = new Section_FromEvent_RankEffect.Description();
			desc.targetPokeCount = 1;
			desc.pokeID = pokeID;
			desc.targetPokeID[0] = pokeID;
			desc.rankType = defence < spDefence ? WazaRankEffect.ATTACK : WazaRankEffect.SP_ATTACK;
			desc.rankVolume = 1;
			desc.isDisplayTokuseiWindow = true;
			Common.RankEffect(args, desc);
		}
		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_Yotimu(ref global::Dpr.Battle.Logic.EventPriority prio) {
			return HandlerTable_Yotimu;
		}
		public static void handler_Yotimu(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;

			MAX_PRIORITY_PARAM[] maxParams = Arrays.InitializeWithDefaultInstances<MAX_PRIORITY_PARAM>(5);
			byte[] opponentPokeID = new byte[5];
			byte count = Common.GetAllOpponentFrontPokeID(args, pokeID, opponentPokeID);
			if (count == 0)
				return;

			byte maxCount = 0;
			byte maxPri = 0;
			for (int i = 0; i < count; i++)
			{
				BTL_POKEPARAM bpp = Common.GetPokeParam(args, opponentPokeID[i]);
				byte wazaCount = bpp.WAZA_GetCount();
				for (byte w = 0; w < wazaCount; w++)
				{
					WazaNo waza = bpp.WAZA_GetID(w);
					// get_yotimu_wazapri inlined
					byte pri = get_yotimu_wazapri(waza);
					if (pri > maxPri)
					{
						maxPri = pri;
						maxCount = 0;
					}

					if (pri == maxPri)
					{
						maxParams[maxCount].pokeID = bpp.GetID();
						maxParams[maxCount].wazaID = waza;
						maxCount++;
					}
				}
			}

			if (maxCount == 0)
				return;

			Common.TokuseiWindow_In(args, pokeID);
			byte idx = (byte)calc.GetRand(maxCount);

			var desc = new Section_FromEvent_Message.Description();
			desc.pokeID = pokeID;
			desc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.YotimuExe);
			desc.message.AddArg(maxParams[idx].pokeID);
			desc.message.AddArg((int)maxParams[idx].wazaID);
			Common.Message(args, desc);
			Common.TokuseiWindow_Out(args, pokeID);
		}
		public static byte get_yotimu_wazapri(global::Pml.WazaNo waza) {
			if (WAZADATA.GetDamageType(waza) == WazaDamageType.NONE)
				return 1;

			uint pow = WAZADATA.GetPower(waza);
			if ((byte)pow != 1)
				return (byte)pow;

			if (WAZADATA.GetCategory(waza) == WazaCategory.ICHIGEKI)
				return 150;

			if (waza == WazaNo.KAUNTAA || waza == WazaNo.MIRAAKOOTO || waza == WazaNo.METARUBAASUTO)
				return 120;

			return 80;
		}
