			return HandlerTable_KikenYoti;
		}
		public static void handler_KikenYoti(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			int targetPokeID = Common.GetEventVar(args, EventVar.Label.POKEID);
			if (targetPokeID != pokeID)
				return;

			if (!check_kikenyoti_enemys(args, pokeID))
				return;

			Common.TokuseiWindow_In(args, pokeID);

			var desc = new Section_FromEvent_Message.Description();
			desc.pokeID = pokeID;
			desc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.Kikenyoti);
			desc.message.AddArg(targetPokeID);
			Common.Message(args, desc);
			Common.TokuseiWindow_Out(args, pokeID);
		}
		public static bool check_kikenyoti_enemys(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, in byte pokeID) {
			byte[] opponentPokeID = new byte[5];
			byte opponentCount = Common.GetAllOpponentFrontPokeID(args, pokeID, opponentPokeID);
			BTL_POKEPARAM bppUser = Common.GetPokeParam(args, pokeID);
			for (int i = 0; i < opponentCount; i++)
			{
				BTL_POKEPARAM bppEnemy = Common.GetPokeParam(args, opponentPokeID[i]);
				if (check_kikenyoti_poke(args, bppUser, bppEnemy))
					return true;
			}

			return false;
		}
		public static bool check_kikenyoti_poke(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, global::Dpr.Battle.Logic.BTL_POKEPARAM bppUser, global::Dpr.Battle.Logic.BTL_POKEPARAM bppEnemy) {
			PokeTypePair pokeType = bppUser.GetPokeType();
			byte wazaCount = bppEnemy.WAZA_GetCount();
			for (byte i = 0; i < wazaCount; i++)
			{
				WazaNo waza = bppEnemy.WAZA_GetID(i);
				if (WAZADATA.GetCategory(waza) == WazaCategory.ICHIGEKI)
					return true;

				if (!WAZADATA.IsDamage(waza))
					continue;

				byte wazaType;
				if (waza == WazaNo.MEZAMERUPAWAA)
					wazaType = Common.GetMezapaType(args, bppEnemy.GetID());
				else
					wazaType = WAZADATA.GetType(waza);

				if (calc.TypeAffPair(wazaType, pokeType) > Pml.Battle.TypeAffinity.AffinityID.TYPEAFF_1)
					return true;
			}

			return false;
		}
		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_Omitoosi(ref global::Dpr.Battle.Logic.EventPriority prio) {
			return HandlerTable_Omitoosi;
		}
		public static void handler_Omitoosi(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			int myPokeID = Common.GetEventVar(args, EventVar.Label.POKEID);
			if (myPokeID != pokeID)
				return;

			byte[] opponentPokeID = new byte[5];
			byte opponentCount = Common.GetAllOpponentFrontPokeID(args, pokeID, opponentPokeID);
			ushort[] itemID = new ushort[5];
			byte[] itemPokeIdx = new byte[5];
			if (opponentCount == 0)
				return;

			byte itemPokeCount = 0;
			for (int i = 0; i < opponentCount; i++)
			{
				BTL_POKEPARAM bpp = Common.GetPokeParam(args, opponentPokeID[i]);
				itemID[i] = bpp.GetItem();
				if (itemID[i] != 0)
					itemPokeIdx[itemPokeCount++] = (byte)i;
			}

			if (itemPokeCount == 0)
				return;

			Common.TokuseiWindow_In(args, pokeID);
			for (int i = 0; i < itemPokeCount; i++)
			{
				// 0194cea4: the description's pokeID is never set; the first message is "Omitoosi" + the holder, the rest
				// "OmitoosiCont"
				var desc = new Section_FromEvent_Message.Description();
				if (i == 0)
				{
					desc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.Omitoosi);
					desc.message.AddArg(myPokeID);
				}
				else
				{
					desc.message.Setup(BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.OmitoosiCont);
				}

				byte idx = itemPokeIdx[i];
				desc.message.AddArg(opponentPokeID[idx]);
				desc.message.AddArg(itemID[idx]);
				Common.Message(args, desc);
			}

			Common.TokuseiWindow_Out(args, pokeID);
		}
