		}
		public static void handler_Kansouhada_Weather(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;

			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			BtlWeather weather = Common.GetLocalWeather(args, pokeID);
			if (calc.IsShineWeather(weather))
			{
				Common.TokuseiWindow_In(args, pokeID);

				var desc = new Section_FromEvent_Damage.Description();
				desc.pokeID = pokeID;
				desc.targetPokeID = pokeID;
				desc.damage = (ushort)calc.QuotMaxHP(bpp, 8, true);
				desc.damageCause = DamageCause.KANSOUHADA;
				desc.damageCausePokeID = Common.GetWeatherCausePokeID(args);
				Common.Damage(args, desc);
				Common.TokuseiWindow_Out(args, pokeID);
			}
			else if (calc.IsRainWeather(weather))
			{
				var desc = new Section_RecoverHP.Description();
				desc.userPokeID = pokeID;
				desc.targetPokeID = pokeID;
				desc.recoverHP = (ushort)calc.QuotMaxHP(bpp, 8, true);
				desc.isDisplayTokuseiWindow = true;
				Common.RecoverHP(args, desc);
			}
		}
