		public static void handler_FusiginaMamori(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			int defPokeID = Common.GetEventVar(args, EventVar.Label.POKEID_DEF);
			if (defPokeID != pokeID)
				return;

			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) == defPokeID)
				return;

			// 0194f5b8: IsDamage is called before the WARUAGAKI compare
			WazaNo waza = (WazaNo)Common.GetEventVar(args, EventVar.Label.WAZAID);
			bool isDamage = WAZADATA.IsDamage(waza);
			if (waza == WazaNo.WARUAGAKI || !isDamage)
				return;

			if (Common.GetEventVar(args, EventVar.Label.TYPEAFF) > (int)Pml.Battle.TypeAffinity.AffinityID.TYPEAFF_1)
				return;

			if (!Common.RewriteEventVar(args, EventVar.Label.NOEFFECT_FLAG, TRUE))
				return;

			Common.RewriteEventVar(args, EventVar.Label.TOKUSEI_WINDOW_DISPLAY, TRUE);
			StrParam strParam = (StrParam)Common.GetEventVarAddress(args, EventVar.Label.WORK_ADRS);
			strParam.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.NoEffect);
			strParam.AddArg(defPokeID);
		}
