				return;

			Common.TokuseiWindow_In(args, pokeID);
			bool isAlreadyActive = Common.GetPokeParam(args, pokeID).CONTFLAG_Get(ContFlag.CONTFLG_MORAIBI);
			// 01950320: the message description is allocated before the branch
			var desc = new Section_FromEvent_Message.Description();
			if (isAlreadyActive)
			{
				desc.pokeID = pokeID;
				desc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.NoEffect);
				desc.message.AddArg(pokeID);
				Common.Message(args, desc);
			}
			else
			{
				desc.pokeID = pokeID;
				desc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.MoraibiExe);
				desc.message.AddArg(pokeID);
				Common.Message(args, desc);

				var contFlagDesc = new Section_FromEvent_SetContFlag.Description();
				contFlagDesc.pokeID = pokeID;
				contFlagDesc.flag = ContFlag.CONTFLG_MORAIBI;
				Common.SetContFlag(args, contFlagDesc);
			}

			Common.TokuseiWindow_Out(args, pokeID);
			Common.RewriteEventVar(args, EventVar.Label.MESSAGE_DISPLAYED, TRUE);
