		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_Nightmare(ref global::Dpr.Battle.Logic.EventPriority prio) {
			return HandlerTable_Nightmare;
		}
		public static void handler_Nightmare(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;

			byte[] targetPokeID = new byte[5];
			var exPos = new ExPokePos(ExPokePos.ExPosType.AREA_ENEMY, Common.GetExistFrontPokePos(args, pokeID));
			byte targetCount = Common.ExpandExistPokeID(args, exPos, targetPokeID);
			if (targetCount == 0)
				return;

			bool isWindowIn = false;
			for (int i = 0; i < targetCount; i++)
			{
				BTL_POKEPARAM target = Common.GetPokeParam(args, targetPokeID[i]);
				if (!target.CheckNemuri(BTL_POKEPARAM.NemuriCheckMode.NEMURI_CHECK_INCLUDE_ZETTAINEMURI))
					continue;

				if (!isWindowIn)
					Common.TokuseiWindow_In(args, pokeID);

				var desc = new Section_FromEvent_Damage.Description();
				desc.pokeID = pokeID;
				desc.targetPokeID = targetPokeID[i];
				desc.damage = (ushort)calc.QuotMaxHP(target, 8, true);
				desc.damageCause = DamageCause.NIGHTMARE;
				desc.damageCausePokeID = pokeID;
				desc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.NightMare);
				desc.successMessage.AddArg(targetPokeID[i]);
				Common.Damage(args, desc);
				isWindowIn = true;
			}

			if (isWindowIn)
				Common.TokuseiWindow_Out(args, pokeID);
		}
