		public static bool handler_Bukiyou_SkipCheck(in global::Dpr.Battle.Logic.EventFactor.SkipCheckHandlerArgs args) {
			// Klutz: skip the holder's own item handlers, except the items in IgnoreItems_Bukiyou and, at ITEMSET_DECIDE, the
			// three choice items
			if (args.factorType != EventFactorType.ITEM)
				return false;

			byte pokeID = args.dependID;
			BTL_POKEPARAM bpp = args.pBattleEnv.GetPokeCon().GetPokeParam(pokeID);
			if (bpp.CheckSick(WazaSick.WAZASICK_IEKI))
				return false;

			if (pokeID != args.pMyFactor.GetPokeID())
				return false;

			ushort itemID = args.subID;
			for (int i = 0; i < IgnoreItems_Bukiyou.Length; i++)
			{
				if (IgnoreItems_Bukiyou[i] == itemID)
					return false;
			}

			if (args.eventID != EventID.ITEMSET_DECIDE)
				return true;

			return itemID != (ushort)ItemNo.KODAWARIHATIMAKI && itemID != (ushort)ItemNo.KODAWARIMEGANE && itemID != (ushort)ItemNo.KODAWARISUKAAHU;
		}
