		public static void handler_Kagefumi(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.IsFriendPokeID(args, (byte)Common.GetEventVar(args, EventVar.Label.POKEID), pokeID))
				return;

			byte[] targetPokeID = new byte[5];
			var exPos = new ExPokePos(ExPokePos.ExPosType.AREA_ENEMY, Common.GetExistFrontPokePos(args, pokeID));
			byte targetCount = Common.ExpandExistPokeID(args, exPos, targetPokeID);
			for (int i = 0; i < targetCount; i++)
			{
				// an opposing Shadow Tag cancels it
				BTL_POKEPARAM bpp = Common.GetPokeParam(args, targetPokeID[i]);
				if (bpp.GetValue(BTL_POKEPARAM.ValueID.BPP_TOKUSEI_EFFECTIVE) == (int)TokuseiNo.KAGEHUMI)
					return;
			}

			Common.RewriteEventVar(args, EventVar.Label.FAIL_FLAG, TRUE);
		}
