		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_Monohiroi(ref global::Dpr.Battle.Logic.EventPriority prio) {
			return HandlerTable_Monohiroi;
		}
		public static void handler_Monohiroi(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			int myPokeID = Common.GetEventVar(args, EventVar.Label.POKEID);
			if (myPokeID != pokeID)
				return;

			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			if (bpp.GetItem() != 0)
				return;

			if (!monohiroi_search(args, pokeID, out byte targetPokeID))
				return;

			ushort itemID = Common.GetPokeParam(args, targetPokeID).GetConsumedItem();
			if (itemID == 0)
				return;

			if (Common.CheckUnbreakablePokeItem(bpp.GetMonsNo(), itemID))
				return;

			var desc = new Section_FromEvent_SetItem.Description();
			desc.userPokeID = pokeID;
			desc.targetPokeID = pokeID;
			desc.itemID = itemID;
			desc.clearConsumePokeID = targetPokeID;
			desc.isClearConsumeOtherPoke = true;
			desc.isDisplayTokuseiWindow = true;
			desc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.Monohiroi);
			desc.successMessage.AddArg(myPokeID);
			desc.successMessage.AddArg(itemID);
			Common.SetItem(args, desc);
		}
		public static bool monohiroi_search(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID, out byte targetPokeID) {
			var exPos = new ExPokePos(ExPokePos.ExPosType.AREA_OTHERS, Common.GetExistFrontPokePos(args, pokeID));
			byte[] otherPokeID = new byte[6];
			byte otherCount = Common.ExpandExistPokeID(args, exPos, otherPokeID);
			byte[] candidatePokeID = new byte[6];
			if (otherCount == 0)
			{
				targetPokeID = 0;
				return false;
			}

			byte candidateCount = 0;
			for (int i = 0; i < otherCount; i++)
			{
				BTL_POKEPARAM bpp = Common.GetPokeParam(args, otherPokeID[i]);
				if (bpp.TURNFLAG_Get(BTL_POKEPARAM.TurnFlag.TURNFLG_ITEM_CONSUMED) && bpp.GetConsumedItem() != 0)
					candidatePokeID[candidateCount++] = bpp.GetID();
			}

			if (candidateCount == 0)
			{
				targetPokeID = 0;
				return false;
			}

			// 019546e8: the random index is cast to byte
			targetPokeID = candidatePokeID[(byte)calc.GetRand(candidateCount)];
			return true;
		}
