				return;

			var desc = new Section_FromEvent_SwapItem.Description();
			desc.userPokeID = pokeID;
			desc.targetPokeID = (byte)atkPokeID;
			desc.isIncRecordCount_StealItemFromWildPoke = true;
			desc.isDisplayTokuseiWindow = true;
			desc.successMessage1.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.WaruiTeguse);
			desc.successMessage1.AddArg((byte)atkPokeID);
			desc.successMessage1.AddArg(targetItem);
