		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_NorowareBody(ref global::Dpr.Battle.Logic.EventPriority prio) {
			return HandlerTable_NorowareBody;
		}
		public static void handler_NorowareBody(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_DEF) != pokeID)
				return;

			if (Common.GetEventVar(args, EventVar.Label.MIGAWARI_FLAG) != 0)
				return;

			if (Common.CheckShowDown(args))
				return;

			int atkPokeID = Common.GetEventVar(args, EventVar.Label.POKEID_ATK);
			BTL_POKEPARAM attacker = Common.GetPokeParam(args, (byte)atkPokeID);
			if (attacker.CheckSick(WazaSick.WAZASICK_KANASIBARI))
				return;

			if (GWaza.IsGWaza((WazaNo)Common.GetEventVar(args, EventVar.Label.WAZAID)))
				return;

			int orgWaza = Common.GetEventVar(args, EventVar.Label.ORG_WAZAID);
			if (orgWaza == (int)WazaNo.NULL || orgWaza == (int)WazaNo.WARUAGAKI)
				return;

			if (tables.IsDelayAttackWaza((WazaNo)orgWaza))
				return;

			if (!isOccurPer(args, 30))
				return;

			// 01954edc: one more turn when the attacker has already acted this turn
			bool isActionDone = attacker.TURNFLAG_Get(BTL_POKEPARAM.TurnFlag.TURNFLG_ACTION_DONE);
			var desc = new Section_AddSick.Description();
			desc.pokeID = pokeID;
			desc.sickID = WazaSick.WAZASICK_KANASIBARI;
			desc.sickCont = SICKCONT.MakeTurnParam(pokeID, (byte)(isActionDone ? 5 : 4), (ushort)orgWaza);
			desc.targetPokeID = (byte)atkPokeID;
			desc.isDisplayTokuseiWindow = true;
			Common.AddSick(args, desc);
		}
