		public static void handler_KudakeruYoroi(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_DEF) != pokeID)
				return;

			if (Common.GetEventVar(args, EventVar.Label.DAMAGE_TYPE) != (int)WazaDamageType.PHYSIC)
				return;

			if (Common.GetEventVar(args, EventVar.Label.MIGAWARI_FLAG) != 0)
				return;

			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			if (!bpp.IsRankEffectValid(BTL_POKEPARAM.ValueID.BPP_DEFENCE_RANK, -1) && !bpp.IsRankEffectValid(BTL_POKEPARAM.ValueID.BPP_AGILITY_RANK, 1))
				return;

			if (bpp.IsDead())
