			desc2.pokeID = pokeID;
			desc2.targetPokeCount = 1;
			desc2.targetPokeID[0] = pokeID;
			desc2.rankType = WazaRankEffect.AGILITY;
			desc2.rankVolume = 2;
			desc2.isSpFailMessageDisplay = true;
			Common.RankEffect(args, desc2);
			Common.TokuseiWindow_Out(args, pokeID);
		}
