		public static bool IsTikarazukuEffecive(global::Pml.WazaNo waza) {
			if (WAZADATA.GetShrinkPer(waza) != 0)
				return true;

			switch (WAZADATA.GetCategory(waza))
			{
				case WazaCategory.DAMAGE_EFFECT_USER:
				{
					// 01955460: boosted unless one of the user's own rank effects is a drop
					byte rankEffectCount = WAZADATA.GetRankEffectCount(waza);
					for (uint i = 0; i < rankEffectCount; i++)
					{
						WAZADATA.GetRankEffect(waza, i, out int volume);
						if (volume < 0)
							return false;
					}

					return true;
				}
				case WazaCategory.DAMAGE_EFFECT:
					return true;
				case WazaCategory.DAMAGE_SICK:
					return WAZADATA.GetSick(waza) != WazaSick.WAZASICK_BIND;
				default:
					return tables.IsTikarazukuEffeciveWaza(waza);
			}
		}
