		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_Murakke(ref global::Dpr.Battle.Logic.EventPriority prio) {
			return HandlerTable_Murakke;
		}
		public static void handler_Murakke(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;

			// 01956a70: the table is read once into a local before the two arrays are allocated; the 5-step loop is unrolled
			WazaRankEffect[] rankTable = handler_MurakkeTable;
			WazaRankEffect[] upRanks = new WazaRankEffect[MURAKKE_RANK_MAX];
			WazaRankEffect[] downRanks = new WazaRankEffect[MURAKKE_RANK_MAX];
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			int upCount = 0;
			int downCount = 0;
			for (int i = 0; i < MURAKKE_RANK_MAX; i++)
			{
				if (bpp.IsRankEffectValid((BTL_POKEPARAM.ValueID)rankTable[i], 1))
					upRanks[upCount++] = rankTable[i];

				if (bpp.IsRankEffectValid((BTL_POKEPARAM.ValueID)rankTable[i], -1))
					downRanks[downCount++] = rankTable[i];
			}

			WazaRankEffect upRank = WazaRankEffect.NONE;
			WazaRankEffect downRank = WazaRankEffect.NONE;
			if (downCount != 0 && upCount == 0)
			{
				downRank = downRanks[calc.GetRand((uint)downCount)];
			}
			else if (downCount == 0 && upCount != 0)
			{
				upRank = upRanks[calc.GetRand((uint)upCount)];
			}
			else if (downCount != 0 && upCount != 0)
			{
				// every (up, down) pair of different stats, as (upIdx << 8) | downIdx, at most MURAKKE_PATTERN_MAX
				ushort[] patterns = new ushort[MURAKKE_PATTERN_MAX];
				byte patternCount = 0;
				for (int u = 0; u < upCount && patternCount < MURAKKE_PATTERN_MAX; u++)
				{
					for (int d = 0; d < downCount && patternCount < MURAKKE_PATTERN_MAX; d++)
					{
						if (upRanks[u] != downRanks[d])
							patterns[patternCount++] = (ushort)((u << 8) | d);
					}
				}

				ushort pattern = patterns[calc.GetRand(patternCount)];
				upRank = upRanks[pattern >> 8];
				downRank = downRanks[pattern & 0xFF];
			}

			Common.TokuseiWindow_In(args, pokeID);
			if (upRank != WazaRankEffect.NONE)
			{
				var desc = new Section_FromEvent_RankEffect.Description();
				desc.targetPokeCount = 1;
				desc.pokeID = pokeID;
				desc.targetPokeID[0] = pokeID;
				desc.rankType = upRank;
				desc.rankVolume = 2;
				Common.RankEffect(args, desc);
			}

			if (downRank != WazaRankEffect.NONE)
			{
				var desc = new Section_FromEvent_RankEffect.Description();
				desc.targetPokeCount = 1;
				desc.pokeID = pokeID;
				desc.targetPokeID[0] = pokeID;
				desc.rankType = downRank;
				desc.rankVolume = -1;
				Common.RankEffect(args, desc);
			}

			Common.TokuseiWindow_Out(args, pokeID);
		}
