		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_SaiseiRyoku(ref global::Dpr.Battle.Logic.EventPriority prio) {
			return HandlerTable_SaiseiRyoku;
		}
		public static void handler_SaiseiRyoku(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;

			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			if (bpp.IsDead() || bpp.IsHPFull())
				return;

			// 0195795c: min(1/3 max HP, max HP - HP), unsigned compare
			uint recoverHP = calc.QuotMaxHP(bpp, 3, true);
			uint lostHP = (uint)(bpp.GetValue(BTL_POKEPARAM.ValueID.BPP_MAX_HP) - bpp.GetValue(BTL_POKEPARAM.ValueID.BPP_HP));
			if (recoverHP > lostHP)
				recoverHP = lostHP;

			var desc = new Section_FromEvent_ShiftHP.Description();
			desc.pokeID = pokeID;
			desc.targetPokeID[0] = pokeID;
			desc.volume[0] = (int)recoverHP;
			desc.targetPokeCount = 1;
			desc.isEffectDisable = true;
			Common.ShiftHP(args, desc);
		}
