		public static bool handler_Surinuke_SkipCheck(in global::Dpr.Battle.Logic.EventFactor.SkipCheckHandlerArgs args) {
			if (args.factorType != EventFactorType.SIDE)
				return false;

			// 019582b8: dependID (byte) vs the side's low byte
			if (args.dependID == (byte)args.pMainModule.PokeIDtoSide(args.pMyFactor.GetPokeID()))
				return false;

			BtlSideEffect sideEffect = (BtlSideEffect)args.subID;
			// 019582d4: `cmp #4 ; b.lo` -> Reflect, Light Screen, Safeguard, Mist
			if (sideEffect <= BtlSideEffect.BTL_SIDEEFF_SIROIKIRI)
				return true;

			return sideEffect == BtlSideEffect.BTL_SIDEEFF_AURORAVEIL;
		}
