		public static global::Pml.WazaData.WazaRankEffect ultraForce_GetEffectRankType(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			WazaRankEffect rankType = WazaRankEffect.ATTACK;
			uint maxValue = 0;
			// 01958be8: unsigned compare, the first strictly larger base stat wins; the static table is re-read every pass
			for (int i = 0; i < RANK_VALUE_TABLE.Length; i++)
			{
				uint value = (uint)bpp.GetValue_Base(RANK_VALUE_TABLE[i].pokeValueID);
				if (maxValue < value)
				{
					rankType = RANK_VALUE_TABLE[i].rankType;
					maxValue = value;
				}
			}
			return rankType;
		}
