		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_Watage(ref global::Dpr.Battle.Logic.EventPriority prio) {
			return HandlerTable_Watage;
		}
		public static void handler_Watage(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_DEF) != pokeID)
				return;

			if (Common.GetEventVar(args, EventVar.Label.MIGAWARI_FLAG) != 0)
				return;

			var exPos = new ExPokePos(ExPokePos.ExPosType.AREA_OTHERS, Common.GetExistFrontPokePos(args, pokeID));
			byte[] pokeIDs = new byte[6];
			byte pokeCount = Common.ExpandExistPokeID(args, exPos, pokeIDs);
			byte[] targetPokeIDs = new byte[6];
			if (pokeCount == 0)
				return;

			byte targetCount = 0;
			for (int i = 0; i < pokeCount; i++)
			{
				BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeIDs[i]);
				if (bpp.CONTFLAG_CheckWazaHide() == ContFlag.CONTFLG_NULL && !bpp.MIGAWARI_IsExist())
					targetPokeIDs[targetCount++] = bpp.GetID();
			}

			if (targetCount == 0)
				return;

			var desc = new Section_FromEvent_RankEffect.Description();
			desc.pokeID = pokeID;
			desc.rankType = WazaRankEffect.AGILITY;
			desc.rankVolume = -1;
			desc.isDisplayTokuseiWindow = true;
			desc.isSpFailMessageDisplay = true;
			desc.targetPokeCount = targetCount;
			for (int i = 0; i < targetCount; i++)
				desc.targetPokeID[i] = targetPokeIDs[i];

			Common.RankEffect(args, desc);
		}
