			if (Common.GetEventVar(args, EventVar.Label.POKEID_DEF) != pokeID)
				return;

			if (Common.GetEventVar(args, EventVar.Label.MIGAWARI_FLAG) != 0)
				return;

			if (Common.CheckShowDown(args))
				return;

			if (Common.GetEventVar(args, EventVar.Label.WAZA_TOUCH_FLAG) == 0)
				return;

			byte atkPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_ATK);
			BTL_POKEPARAM attacker = Common.GetPokeParam(args, atkPokeID);
			if (attacker.GetValue(BTL_POKEPARAM.ValueID.BPP_TOKUSEI) == (int)TokuseiNo.MIIRA)
				return;

			var desc = new Section_FromEvent_ChangeTokusei.Description();
			desc.tokuseiID = TokuseiNo.MIIRA;
			desc.userPokeID = pokeID;
			desc.targetPokeID = atkPokeID;
			desc.cause = TokuseiChangeCause.TOKUSEI_CHANGE_CAUSE_MIIRA;
			desc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.Miira);
			desc.successMessage.AddArg(atkPokeID);
			if (!Common.IsFriendPokeID(args, pokeID, atkPokeID))
				desc.isDisplayTokuseiWindow = true;

			Common.ChangeTokusei(args, desc);
		}
