			// one message per move serial (work[1])
			int wazaSerial = Common.GetEventVar(args, EventVar.Label.WAZA_SERIAL);
			if (wazaSerial != 0 && Common.GetWorkValue(args, WIDX1) == wazaSerial)
				return;

			byte targetPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID);
			common_RankDownGuard_Fixed(args, targetPokeID, pokeID, BTL_STRID_SET.FlowerVeil);
