		public static void handler_FlowerVeil_SickCheck(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			byte targetPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_DEF);
			if (!common_IsFlowerVeilTarget(args, pokeID, targetPokeID))
				return;

			// 0195c03c: `eor` of the two ids, byte-masked
			if ((byte)Common.GetEventVar(args, EventVar.Label.POKEID_ATK) == targetPokeID)
				return;

			WazaSick sickID = (WazaSick)Common.GetEventVar(args, EventVar.Label.SICKID);
			if (BattleCommon.IsPokeSick(sickID) || sickID == WazaSick.WAZASICK_AKUBI)
			{
				bool isFailed = Common.RewriteEventVar(args, EventVar.Label.FAIL_FLAG, TRUE);
				Common.SetWorkValue(args, WIDX0, isFailed ? 1 : 0);
			}
		}
