			int wazaSerial = Common.GetEventVar(args, EventVar.Label.WAZA_SERIAL);
			if (wazaSerial != 0 && Common.GetWorkValue(args, WIDX1) == wazaSerial)
				return;

			common_FriendSickFailed(args, pokeID, BTL_STRID_SET.FlowerVeil);
			Common.SetWorkValue(args, WIDX1, wazaSerial);
		}
