		public static bool checkMirrorArmorCause(global::Dpr.Battle.Logic.RankEffectCause cause) {
			// 0195c6a0: (cause - 5) < 2 || (cause - 8) < 3, byte arithmetic
			if (cause == RankEffectCause.RAID_BOSS_EXTRA_ATTACK || cause == RankEffectCause.RAID_BOSS_BREAK_GWALL)
				return true;

			return cause == RankEffectCause.CHEER || cause == RankEffectCause.MIRRORARMOR || cause == RankEffectCause.TAKOGATAME;
		}
		public static void handler_MirroArmor_Check(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_DEF) != pokeID)
				return;

			if (Common.GetEventVar(args, EventVar.Label.VOLUME) >= 0)
				return;

			// checkMirrorArmorCause inlined (0195c7c0: `and #0xff ; cmp #0xa ; lsl ; tst #0x760`)
			if (checkMirrorArmorCause((RankEffectCause)Common.GetEventVar(args, EventVar.Label.RANKEFFECT_CAUSE)))
				return;

			// 0195c818: the holder's id vs the attacker's low byte
			if ((byte)Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				Common.RewriteEventVar(args, EventVar.Label.REFLECT_FLAG, TRUE);
		}
		public static void handler_MirroArmor_Reflect(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_DEF) != pokeID)
				return;

			byte atkPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_ATK);
			int statusType = Common.GetEventVar(args, EventVar.Label.STATUS_TYPE);
			int volume = Common.GetEventVar(args, EventVar.Label.VOLUME);
			if (atkPokeID == PokeID.INVALID)
				return;

			var desc = new Section_FromEvent_RankEffect.Description();
			desc.cause = RankEffectCause.MIRRORARMOR;
			desc.pokeID = pokeID;
			desc.rankType = (WazaRankEffect)statusType;
			desc.rankVolume = (sbyte)volume;
			desc.targetPokeCount = 1;
			desc.targetPokeID[0] = atkPokeID;
			desc.isDisplayTokuseiWindow = true;
			desc.isSpFailMessageDisplay = true;
			Common.RankEffect(args, desc);
		}
