		}
		public static void handler_HengenZizai(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;

			// 0195cd54: byte type below NULL (`and #0xfe ; cmp #0x11`)
			byte wazaType = (byte)Common.GetEventVar(args, EventVar.Label.WAZA_TYPE);
			if (wazaType >= (byte)PokeType.NULL)
				return;

			var desc = new Section_FromEvent_ChangePokeType.Description();
			desc.pokeID = pokeID;
			desc.nextType = PokeTypePair.MakePure(wazaType);
			desc.exTypeCause = BTL_POKEPARAM.ExTypeCause.EXTYPE_CAUSE_NONE;
