			if (Common.GetEventVar(args, EventVar.Label.POKEID_DEF) != pokeID)
				return;

			if (!tables.IsBoudanWaza((WazaNo)Common.GetEventVar(args, EventVar.Label.WAZAID)))
				return;

			if (!Common.RewriteEventVar(args, EventVar.Label.NOEFFECT_FLAG, TRUE))
