		public static void handler_magician_Start(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			Common.Dorobou_Start(args, pokeID);
		}
		public static void handler_magician(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetRule(args) == BtlRule.BTL_RULE_RAID)
				return;

			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;

			if (!Common.Dorobou_CheckEnable(args, pokeID))
				return;

			if (Common.GetEventVar(args, EventVar.Label.DELAY_ATTACK_FLAG) != 0)
				return;

			byte[] targetPokeIDAry = new byte[6];
			uint targetCount = (uint)Common.GetEventVar(args, EventVar.Label.TARGET_POKECNT);
			for (int i = 0; i < targetCount; i++)
				targetPokeIDAry[i] = (byte)Common.GetEventVar(args, (EventVar.Label)((int)EventVar.Label.POKEID_TARGET1 + i));

			Common.SortTargetsByAgility(args, targetPokeIDAry, targetCount, pokeID, true);
			for (int i = 0; i < targetCount; i++)
			{
				if (magician_swapitem(args, pokeID, targetPokeIDAry[i]))
					break;
			}

			args.pMyFactor.ClearWork();
		}
		public static bool magician_swapitem(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID, byte targetPokeID) {
			ushort itemID = Common.GetPokeParam(args, targetPokeID).GetItem();
			if (itemID == 0)
				return false;

			if (Common.CheckCantStealPoke(args, pokeID, targetPokeID))
				return false;

			var desc = new Section_FromEvent_SwapItem.Description();
			desc.userPokeID = pokeID;
			desc.targetPokeID = targetPokeID;
			desc.isIncRecordCount_StealItemFromWildPoke = true;
			desc.isDisplayTokuseiWindow = true;
			desc.successMessage1.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.Dorobou);
			desc.successMessage1.AddArg(pokeID);
			desc.successMessage1.AddArg(targetPokeID);
			desc.successMessage1.AddArg(itemID);
			Common.SwapItem(args, desc);
			return true;
		}
		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_Kyousei(ref global::Dpr.Battle.Logic.EventPriority prio) {
			return HandlerTable_Kyousei;
		}
		public static void handler_kyousei_wazaSeqStart(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			Common.SetWorkValue(args, WIDX0, 1);
			Common.SetWorkValue(args, WIDX1, PokeID.INVALID);
		}
		public static void handler_kyousei_wazaSeqEnd(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetWorkValue(args, WIDX0) == 0)
				return;

			// 0195f7ec: the stored target is compared as a byte
			byte targetPokeID = (byte)Common.GetWorkValue(args, WIDX1);
			if (targetPokeID != PokeID.INVALID)
			{
				kyousei_commonProc(args, pokeID, targetPokeID);
				Common.SetWorkValue(args, WIDX1, PokeID.INVALID);
			}

			Common.SetWorkValue(args, WIDX0, 0);
		}
		public static void handler_kyousei(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			byte targetPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID);
			if (!Common.IsFriendPokeID(args, pokeID, targetPokeID))
				return;

			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			BTL_POKEPARAM target = Common.GetPokeParam(args, targetPokeID);
			if (bpp.GetItem() == 0 || target.GetItem() != 0)
				return;

			if (bpp.TURNFLAG_Get(BTL_POKEPARAM.TurnFlag.TURNFLG_NAGETUKERU_USING) || bpp.TURNFLAG_Get(BTL_POKEPARAM.TurnFlag.TURNFLG_RESERVE_ITEM_SPEND))
				return;

			// during the holder's own move sequence the handover waits for wazaSeqEnd
			if (Common.GetWorkValue(args, WIDX0) != 0)
				Common.SetWorkValue(args, WIDX1, targetPokeID);
			else
				kyousei_commonProc(args, pokeID, targetPokeID);
		}
		public static void kyousei_commonProc(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID, byte targetPokeID) {
			if (Common.GetRule(args) == BtlRule.BTL_RULE_RAID)
				return;

			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			BTL_POKEPARAM target = Common.GetPokeParam(args, targetPokeID);
			if (!Common.IsFriendPokeID(args, pokeID, targetPokeID))
				return;

			if (Common.GetExistFrontPokePos(args, targetPokeID) == BtlPokePos.POS_NULL)
				return;

			ushort itemID = bpp.GetItem();
			if (itemID == 0 || target.GetItem() != 0)
				return;

			if (Common.CheckUnbreakablePokeItem(target.GetMonsNo(), itemID))
				return;

			if (Common.CheckUnbreakablePokeItem(bpp.GetMonsNo(), itemID))
				return;

			var desc = new Section_FromEvent_SwapItem.Description();
			desc.isDisplayTokuseiWindow = true;
			desc.userPokeID = pokeID;
			desc.targetPokeID = targetPokeID;
			desc.successMessage1.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.Kyousei);
			desc.successMessage1.AddArg(pokeID);
			desc.successMessage1.AddArg(itemID);
			desc.successMessage1.AddArg(targetPokeID);
			Common.SwapItem(args, desc);
		}
