		public static void handler_Zyoounoigen_WazaExeCheck(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			byte atkPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID);
			if (Common.GetEventVar(args, EventVar.Label.WAZA_PRI) <= 0)
				return;

			// 019610a4 / 019610bc: MainModule called directly (no Common class-init test before them)
			if (args.pMainModule.IsFriendPokeID(pokeID, atkPokeID))
				return;

			if (!Common.CheckTargetSide(args, args.pMainModule.PokeIDtoSide(pokeID)))
				return;

			if (!Common.RewriteEventVar(args, EventVar.Label.FAIL_CAUSE, (int)WazaFailCause.TOKUSEI))
				return;

			var desc = new Section_FromEvent_Message.Description();
			desc.pokeID = pokeID;
			desc.isDisplayTokuseiWindow = true;
			desc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.WazaCantUse);
			desc.message.AddArg(atkPokeID);
			desc.message.AddArg(Common.GetEventVar(args, EventVar.Label.WAZAID));
			Common.Message(args, desc);
		}
