		public static void handler_Receiver_DeadAfter(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			byte deadPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID);
			if (deadPokeID == pokeID)
				return;

			if (!Common.IsFriendPokeID(args, pokeID, deadPokeID))
				return;

			TokuseiNo tokuseiID = (TokuseiNo)Common.GetPokeParam(args, deadPokeID).GetValue(BTL_POKEPARAM.ValueID.BPP_TOKUSEI);
			if (tokuseiID == TokuseiNo.NULL)
				return;

			if (tables.CheckReceiverFailTokusei(tokuseiID))
				return;

			var desc = new Section_FromEvent_ChangeTokusei.Description();
			desc.userPokeID = pokeID;
			desc.targetPokeID = pokeID;
			desc.tokuseiID = tokuseiID;
			desc.isSkipMemberInEvent = true;
			desc.isDisplayTokuseiWindow = true;
			desc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.Receiver);
			desc.successMessage.AddArg(deadPokeID);
			desc.successMessage.AddArg((ushort)tokuseiID);
			Common.ChangeTokusei(args, desc);
		}
