		public static void tobidasuNakami_RegisterDamage(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			// the HP before the hit (before-Dynamax value) is the damage dealt back
			Common.SetWorkValue(args, WIDX0, Common.GetPokeParam(args, pokeID).GetValue(BTL_POKEPARAM.ValueID.BPP_HP_BEFORE_G));
		}
		public static void handler_TobidasuNakami_WazaDamageReaction(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			byte atkPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_ATK);
			if ((byte)Common.GetEventVar(args, EventVar.Label.POKEID_DEF) != pokeID)
				return;

			if (Common.GetWorkValue(args, WIDX0) <= 0)
				return;

			BTL_POKEPARAM attacker = Common.GetPokeParam(args, atkPokeID);
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			if (attacker.IsDead() || !bpp.IsDead())
				return;

			var desc = new Section_FromEvent_Damage.Description();
			desc.pokeID = pokeID;
			desc.targetPokeID = atkPokeID;
			desc.damage = (ushort)Common.GetWorkValue(args, WIDX0);
			desc.damageCause = DamageCause.TOBIDASUNAKAMI;
			desc.damageCausePokeID = pokeID;
			desc.disableDeadProcess = true;
			desc.isDisplayTokuseiWindow = true;
			desc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.SimpleDamage);
			desc.successMessage.AddArg(atkPokeID);
			Common.Damage(args, desc);
			Common.SetWorkValue(args, WIDX0, 0);
		}
