		public static bool gyakuzyou_isEnoughHP(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			return calc.QuotMaxHP_Zero(bpp, 2, false) < (uint)bpp.GetValue(BTL_POKEPARAM.ValueID.BPP_HP);
		}
		public static void handler_Gyakuzyou_EndHitReal(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.CheckShowDown(args))
				return;

			if (!common_CheckTarget(args, pokeID))
				return;

			if (Common.GetWorkValue(args, WIDX0) != 1)
				return;

			// written out here (no gyakuzyou_isEnoughHP init flag in this method): HP fell to half or below
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			uint halfHP = calc.QuotMaxHP_Zero(bpp, 2, false);
			if ((uint)bpp.GetValue(BTL_POKEPARAM.ValueID.BPP_HP) > halfHP)
				return;

			var desc = new Section_FromEvent_RankEffect.Description();
			desc.pokeID = pokeID;
			desc.targetPokeCount = 1;
			desc.targetPokeID[0] = pokeID;
			desc.rankType = WazaRankEffect.SP_ATTACK;
			desc.rankVolume = 1;
			desc.isDisplayTokuseiWindow = true;
			Common.RankEffect(args, desc);
			Common.SetWorkValue(args, WIDX0, 0);
		}
		public static bool common_CheckTarget(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte checkPokeID) {
			int targetCount = Common.GetEventVar(args, EventVar.Label.TARGET_POKECNT);
			for (int i = 0; i < targetCount; i++)
			{
				if (Common.GetEventVar(args, (EventVar.Label)((int)EventVar.Label.POKEID_TARGET1 + i)) == checkPokeID)
					return true;
			}
			return false;
		}
