		public static void handler_Nigegosi_EndHit(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			// work[1] == 2: the holder's own move hurt it below half (recoil etc.) - switch out after the move
			if (Common.GetWorkValue(args, WIDX1) == 2 && Common.GetEventVar(args, EventVar.Label.POKEID_ATK) == pokeID)
			{
				nigegosi_AfterDamage_Effect(args, pokeID);
				return;
			}

			if (common_CheckTarget(args, pokeID) && Common.GetEventVar(args, EventVar.Label.OIUTI_INTERRUPT_FLAG) == 0)
				nigegosi_AfterDamage_Full(args, pokeID);
		}
		public static void handler_Nigegosi_SimpleDamageBefore(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) == pokeID)
				nigegosi_CheckBeforeDamage(args, pokeID);
		}
		public static void handler_Nigegosi_SimpleDamageAfter(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;

			if (!nigegosi_AfterDamage_shouldEffect(args, pokeID))
				return;

			Common.SetWorkValue(args, WIDX0, 0);
			if (Common.GetWorkValue(args, WIDX1) != 1)
				nigegosi_AfterDamage_Effect(args, pokeID);
			else
				Common.SetWorkValue(args, WIDX1, 2);
		}
		public static void nigegosi_CheckBeforeDamage(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			uint halfHP = calc.QuotMaxHP_Zero(bpp, 2, false);
			uint hp = (uint)bpp.GetValue(BTL_POKEPARAM.ValueID.BPP_HP);
			Common.SetWorkValue(args, WIDX0, halfHP < hp ? 1 : 0);
		}
		public static void nigegosi_AfterDamage_Full(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (!nigegosi_AfterDamage_shouldEffect(args, pokeID))
				return;

			Common.SetWorkValue(args, WIDX0, 0);
			nigegosi_AfterDamage_Effect(args, pokeID);
		}
		public static bool nigegosi_AfterDamage_shouldEffect(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.CheckShowDown(args))
				return false;

			if (Common.CheckMemberOutInterruptActionProceeding(args))
				return false;

			// work[0] = 1: HP was above half before the damage
			if (Common.GetWorkValue(args, WIDX0) != 1)
				return false;

			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			uint halfHP = calc.QuotMaxHP_Zero(bpp, 2, false);
			uint hp = (uint)bpp.GetValue(BTL_POKEPARAM.ValueID.BPP_HP);
			if (hp > halfHP)
				return false;

			return hp != 0;
		}
		public static void nigegosi_AfterDamage_Effect(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (nigegosi_isQuitBattle(args))
			{
				var desc = new Section_FromEvent_QuitBattle.Description();
				desc.userPokeID = pokeID;
				desc.isForceSuccess = true;
				desc.isDisplayTokuseiWindow = true;
				Common.QuitBattle(args, desc);
			}
			else if (Common.CheckChangeEnablePokeExist(args, pokeID))
			{
				var desc = new Section_FromEvent_MemberChange.Description();
				desc.outPokeID = pokeID;
				desc.isInterruptDisable = true;
				desc.isDisplayTokuseiWindow = true;
				Common.MemberChange(args, desc);
			}
		}
		public static bool nigegosi_isQuitBattle(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args) {
			if (!Common.IsEscapeEnableBattle(args))
				return false;

			if (Common.GetRule(args) == BtlRule.BTL_RULE_RAID)
				return false;

			return Common.GetCompetitor(args) == BtlCompetitor.BTL_COMPETITOR_WILD;
		}
