		public static void handler_Odoriko_ExecuteEffective(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetWorkValue(args, WIDX0) != 0)
				return;

			if (Common.GetWorkValue(args, WIDX2) == 0)
				return;

			if (Common.GetEventVar(args, EventVar.Label.ACTION_DESC_IS_YOKODORI_ROB_ACTION) != 0)
				return;

			if (Common.GetEventVar(args, EventVar.Label.ACTION_DESC_IS_MAGICCOAT_REACTION) != 0)
				return;

			if (Common.GetEventVar(args, EventVar.Label.ACTION_DESC_IS_ODORIKO_REACTION) != 0)
				return;

			if (Common.GetEventVar(args, EventVar.Label.POKEID) == pokeID)
				return;

			if (Common.GetPokeParam(args, pokeID).IsWazaHide())
				return;

			int waza = Common.GetEventVar(args, EventVar.Label.WAZAID);
			if (WAZADATA.GetFlag((WazaNo)waza, WazaFlag.DANCE))
			{
				Common.SetWorkValue(args, WIDX0, 1);
				Common.SetWorkValue(args, WIDX1, waza);
			}
		}
		public static void handler_Odoriko_WazaSeqEnd(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			Common.SetWorkValue(args, WIDX2, 0);
			if (Common.GetWorkValue(args, WIDX0) != 1)
				return;

			BtlPokePos targetPos = odoriko_GetTargetPos(args, pokeID, (byte)Common.GetEventVar(args, EventVar.Label.POKEID));
			if (targetPos != BtlPokePos.POS_NULL)
			{
				var desc = new Section_FromEvent_InsertWazaAction.Description();
				desc.actPokeID = pokeID;
				desc.actWazaNo = (WazaNo)Common.GetWorkValue(args, WIDX1);
				desc.targetPos = targetPos;
				desc.actionDesc.isOdorikoReaction = true;
				desc.actionDesc.insertInfo.isTokuseiWindowDisplay = true;
				Common.InsertWazaAction(args, desc);
			}

			Common.SetWorkValue(args, WIDX0, 0);
		}
		public static global::Dpr.Battle.Logic.BtlPokePos odoriko_GetTargetPos(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte odorikoPokeID, byte attackPokeID) {
			// a friend's dance is copied onto the friend's own target unless that target was the dancer itself
			if (Common.IsFriendPokeID(args, odorikoPokeID, attackPokeID))
			{
				BTL_POKEPARAM attacker = Common.GetPokeParam(args, attackPokeID);
				BtlPokePos myPos = Common.GetExistFrontPokePos(args, odorikoPokeID);
				BtlPokePos prevTargetPos = attacker.GetPrevTargetPos();
				if (prevTargetPos != myPos)
					return prevTargetPos;
			}

			return Common.GetPokeLastPos(args, attackPokeID);
		}
