		public static void common_GroundMaker(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID, global::Dpr.Battle.Logic.BtlGround ground) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;

			if (Common.GetGround(args) == ground)
				return;

			var desc = new Section_FieldEffect_Add.Description();
			desc.pokeID = pokeID;
			desc.effect = EffectType.EFF_GROUND;
