		public static void handler_Gitai_Change(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			byte typeEx = bpp.GetExType();
			byte type1;
			byte type2;
			bool isRestore;
			// 019642c0: terrain 1..4 -> type from the packed immediate 0xd0c110b, anything else restores the original types
			switch (Common.GetGround(args))
			{
				case BtlGround.BTL_GROUND_GRASS:
					type1 = type2 = (byte)PokeType.KUSA;
					isRestore = false;
					break;
				case BtlGround.BTL_GROUND_MIST:
					type1 = type2 = (byte)PokeType.FAIRY;
					isRestore = false;
					break;
				case BtlGround.BTL_GROUND_ELEKI:
					type1 = type2 = (byte)PokeType.DENKI;
					isRestore = false;
					break;
				case BtlGround.BTL_GROUND_PHYCHO:
					type1 = type2 = (byte)PokeType.ESPER;
					isRestore = false;
					break;
				default:
					type1 = bpp.GetOriginalPokeType1();
					type2 = bpp.GetOriginalPokeType2();
					isRestore = true;
					break;
			}

			var desc = new Section_FromEvent_ChangePokeType.Description();
			desc.pokeID = pokeID;
			desc.nextType = PokeTypePair.Make(type1, type2, typeEx);
			desc.exTypeCause = bpp.GetExTypeCause();
			desc.isDisplayTokuseiWindow = true;
			if (isRestore)
			{
				desc.isStandardMessageDisable = true;
				desc.changedMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.Gitai);
				desc.changedMessage.AddArg(pokeID);
			}

			Common.ChangeType(args, desc);
		}
