		public static void handler_ZettaiNemuri_AddSickCheckFail(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			// InitializeArray @ global-metadata 0x667319 = {1, 2, 3, 4, 5, 14}
			WazaSick[] guardSicks = new WazaSick[]
			{
				WazaSick.WAZASICK_MAHI, WazaSick.WAZASICK_NEMURI, WazaSick.WAZASICK_KOORI,
				WazaSick.WAZASICK_YAKEDO, WazaSick.WAZASICK_DOKU, WazaSick.WAZASICK_AKUBI,
			};
			for (int i = 0; i < guardSicks.Length; i++)
			{
				bool isGuarded = Common.GuardWazaSick(args, pokeID, guardSicks[i]);
				Common.SetWorkValue(args, WIDX0, isGuarded ? 1 : 0);
				if (isGuarded)
					return;
			}
		}
